-- Free-plan capacity overlay. Only storage admission changes; financial profiles,
-- positions, request quotas, transfer counters and per-study allocations are retained.
begin;
set local lock_timeout='5s';
create table if not exists paperlab.storage_budget_runtime(singleton boolean primary key default true check(singleton),policy jsonb not null,applied_at timestamptz not null default now());
create table if not exists paperlab.storage_budget_patches(signature text primary key,before_hash text not null,after_hash text not null,applied_at timestamptz not null default now());
alter table paperlab.storage_budget_runtime enable row level security;
alter table paperlab.storage_budget_patches enable row level security;
revoke all on paperlab.storage_budget_runtime,paperlab.storage_budget_patches from public,anon,authenticated,service_role;
insert into paperlab.storage_budget_runtime(singleton,policy)values(true,'{"version":"storage-capacity-v1","provider_database_bytes":500000000,"warning_bytes":350000000,"soft_bytes":400000000,"hard_bytes":450000000,"provider_object_bytes":1000000000,"object_warning_bytes":600000000,"object_hard_bytes":800000000,"quota_evidence":"Owner Supabase Free usage screenshot, 19 November 2026","provider_meter_live":false,"financial_rules_changed":false}')on conflict do nothing;
alter table paperlab.free_usage drop constraint if exists free_usage_max_database_bytes_check;
alter table paperlab.free_usage add constraint free_usage_max_database_bytes_check check(max_database_bytes between 1 and 450000000);
alter table paperlab.free_usage alter column max_database_bytes set default 450000000;
update paperlab.free_usage set max_database_bytes=450000000 where month=date_trunc('month',now()at time zone'UTC')::date and max_database_bytes=300000000;
create or replace function paperlab.storage_limit(p_level text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,pg_temp as $$declare n bigint;cap bigint;begin
 if p_level not in('warning','soft','hard')then raise exception 'Unknown storage limit';end if;
 select(policy->>(p_level||'_bytes'))::bigint into n from paperlab.storage_budget_runtime where singleton;
 select max_database_bytes into cap from paperlab.free_usage where month=date_trunc('month',now()at time zone'UTC')::date;
 if n is null then raise exception 'Storage policy missing';end if;return least(n,coalesce(cap,450000000));end$$;
revoke all on function paperlab.storage_limit(text)from public,anon,authenticated,service_role;
do $patch$declare item jsonb;rule jsonb;proc regprocedure;definition text;original text;n int;begin
 for item in select value from jsonb_array_elements($rules$[{"signature":"paper_company_research_save(jsonb)","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paperlab.retain_research_version()","rules":[{"old":"pg_database_size(current_database())>=100000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_project_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_project_watch_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_project_backup_input()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('hard')","count":1},{"old":"if r.archive_bytes+50000000>300000000","new":"if (select coalesce(sum((metadata->>'size')::bigint),0)from storage.objects)+15000000>(select(policy->>'object_hard_bytes')::bigint from paperlab.storage_budget_runtime where singleton)or r.archive_bytes+50000000>300000000","count":1}]},{"signature":"paper_opportunity_guard()","rules":[{"old":"pg_database_size(current_database())>=200000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_earnings_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_quarterly_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_claim_research()","rules":[{"old":"pg_database_size(current_database())>=250000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_consensus_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_learning_budget_guard()","rules":[{"old":"pg_database_size(current_database())<250000000","new":"pg_database_size(current_database())<paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_scoped_research_save(uuid,jsonb)","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_audit_input()","rules":[{"old":"pg_database_size(current_database())>=250000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_learning_train_input()","rules":[{"old":"pg_database_size(current_database())>=300000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_daily_claim()","rules":[{"old":"pg_database_size(current_database())>=200000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_history_claim_transport_v1()","rules":[{"old":"pg_database_size(current_database())>=180000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_gemini_claim()","rules":[{"old":"pg_database_size(current_database())>100000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_candidates_claim()","rules":[{"old":"pg_database_size(current_database())>=120000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_deep_claim()","rules":[{"old":"pg_database_size(current_database())>99000000","new":"pg_database_size(current_database())>paperlab.storage_limit('hard')","count":1}]},{"signature":"paper_reading_claim()","rules":[{"old":"pg_database_size(current_database())>=100000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_capital_claim_base_v1(uuid,bigint)","rules":[{"old":"pg_database_size(current_database())>=150000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('hard')","count":1},{"old":"pg_database_size(current_database())<120000000","new":"pg_database_size(current_database())<paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_iex_claim()","rules":[{"old":"pg_database_size(current_database())>=105000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_company_collect_claim()","rules":[{"old":"(r.policy->>'max_database_bytes')::bigint","new":"paperlab.storage_limit('soft')","count":1}]},{"signature":"paperlab.deep_add_document(jsonb)","rules":[{"old":"pg_database_size(current_database())>97000000","new":"pg_database_size(current_database())>paperlab.storage_limit('soft')","count":1}]},{"signature":"paper_company_coverage_claim_source_base_v1(boolean)","rules":[{"old":"(r.policy->>'max_database_bytes')::bigint","new":"paperlab.storage_limit('soft')","count":1}]},{"signature":"paperlab.weekly_build(timestamp with time zone,boolean)","rules":[{"old":"pg_database_size(current_database())>=100000000","new":"pg_database_size(current_database())>=paperlab.storage_limit('soft')","count":1}]}]$rules$::jsonb)loop
  proc:=to_regprocedure(item->>'signature');if proc is null then continue;end if;
  definition:=pg_get_functiondef(proc);original:=definition;
  for rule in select value from jsonb_array_elements(item->'rules')loop
   n:=(length(definition)-length(replace(definition,rule->>'old','')))/length(rule->>'old');
   if n=0 and strpos(definition,rule->>'new')>0 then continue;end if;
   if n<>(rule->>'count')::int then raise exception 'Unexpected storage guard: % / %',proc,rule->>'old';end if;
   definition:=replace(definition,rule->>'old',rule->>'new');
  end loop;
  if definition<>original then execute definition;insert into paperlab.storage_budget_patches(signature,before_hash,after_hash)values(proc::text,encode(sha256(convert_to(original,'UTF8')),'hex'),encode(sha256(convert_to(pg_get_functiondef(proc),'UTF8')),'hex'))on conflict(signature)do update set before_hash=excluded.before_hash,after_hash=excluded.after_hash,applied_at=now();end if;
  if to_regclass('paperlab.traffic_budget_patches')is not null then update paperlab.traffic_budget_patches set after_hash=encode(sha256(convert_to(pg_get_functiondef(proc),'UTF8')),'hex')where signature=proc::text;end if;
 end loop;
end$patch$;
create or replace function public.paper_storage_budget_read(p_owner uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare db bigint:=pg_database_size(current_database());objects bigint;policy jsonb;begin
 if p_owner is distinct from(select owner_id from paperlab.settings where singleton)then raise exception 'Owner required';end if;
 select r.policy into policy from paperlab.storage_budget_runtime r where singleton;
 select coalesce(sum((metadata->>'size')::bigint),0)into objects from storage.objects;
 return jsonb_build_object('checked_at',now(),'policy',policy,'database_bytes',db,'warning_bytes',paperlab.storage_limit('warning'),'soft_bytes',paperlab.storage_limit('soft'),'hard_bytes',paperlab.storage_limit('hard'),'database_status',case when db>=paperlab.storage_limit('hard')then'hard_stop'when db>=paperlab.storage_limit('soft')then'new_sources_paused'when db>=paperlab.storage_limit('warning')then'warning'else'available'end,'object_bytes',objects,'object_status',case when objects>=(policy->>'object_hard_bytes')::bigint then'hard_stop'when objects>=(policy->>'object_warning_bytes')::bigint then'warning'else'available'end,'largest_tables',(select jsonb_agg(x)from(select schemaname,relname,pg_total_relation_size(relid)bytes from pg_stat_user_tables order by pg_total_relation_size(relid)desc limit 8)x),'note','Database, bestandsopslag en maandelijks verkeer zijn afzonderlijke meters. Providerdashboard kan vertraagd zijn en anders meten. Bewaak groei; bestaande deelbudgetten en onderzoeksvalidatie blijven gelden.');
end$$;
do $$begin if to_regprocedure('public.paper_traffic_budget_storage_base_v1(uuid)')is null then alter function public.paper_traffic_budget_read(uuid)rename to paper_traffic_budget_storage_base_v1;end if;end$$;
create or replace function public.paper_traffic_budget_read(p_owner uuid)returns jsonb language sql security definer set search_path=pg_catalog,pg_temp as $$select public.paper_traffic_budget_storage_base_v1(p_owner)||jsonb_build_object('storage',public.paper_storage_budget_read(p_owner))$$;
revoke all on function public.paper_storage_budget_read(uuid),public.paper_traffic_budget_storage_base_v1(uuid),public.paper_traffic_budget_read(uuid)from public,anon,authenticated,service_role;
grant execute on function public.paper_storage_budget_read(uuid),public.paper_traffic_budget_read(uuid)to service_role;
commit;
